from flask import Flask, abort

app = Flask(__name__)
app.config['TESTING'] = True
TOPICS = {7: 'Loops'}

@app.get('/topics/<int:topic_id>')
def get_topic(topic_id):
    title = TOPICS.get(topic_id)
    if title is None:
        abort(404)
    return {'id': topic_id, 'title': title}

client = app.test_client()
found = client.get('/topics/7')
missing = client.get('/topics/8')
print(found.status_code, found.json['title'])
print(missing.status_code)

